describe('Delete Single Notification', () => {
  beforeEach(() => {
    cy.visit('/notifications');
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          {
            id: '1',
            title: 'Test Notification 1',
            message: 'This is a test notification',
            timestamp: '2024-01-15T10:30:00Z',
            read: false
          },
          {
            id: '2',
            title: 'Test Notification 2',
            message: 'This is another test notification',
            timestamp: '2024-01-15T10:25:00Z',
            read: true
          },
          {
            id: '3',
            title: 'Test Notification 3',
            message: 'Third test notification',
            timestamp: '2024-01-15T10:20:00Z',
            read: false
          }
        ]
      }
    }).as('getNotifications');

    cy.intercept('DELETE', '/api/notifications/*', {
      statusCode: 200,
      body: { success: true }
    }).as('deleteNotification');

    cy.wait('@getNotifications');
  });

  it('should delete a single notification from the list', () => {
    cy.get('[data-testid="notification-item"]').should('have.length', 3);

    cy.get('[data-testid="notification-item"]').first().within(() => {
      cy.get('[data-testid="delete-notification-btn"]').click();
    });

    cy.get('[data-testid="delete-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.wait('@deleteNotification');

    cy.get('[data-testid="notification-item"]').should('have.length', 2);
    cy.get('[data-testid="success-toast"]').should('contain', 'Notification deleted successfully');
  });

  it('should handle deletion of last remaining notification', () => {
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          {
            id: '1',
            title: 'Last Notification',
            message: 'This is the last notification',
            timestamp: '2024-01-15T10:30:00Z',
            read: false
          }
        ]
      }
    }).as('getSingleNotification');

    cy.reload();
    cy.wait('@getSingleNotification');

    cy.get('[data-testid="notification-item"]').should('have.length', 1);

    cy.get('[data-testid="notification-item"]').within(() => {
      cy.get('[data-testid="delete-notification-btn"]').click();
    });

    cy.get('[data-testid="delete-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.wait('@deleteNotification');

    cy.get('[data-testid="notification-item"]').should('not.exist');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No notifications');
  });

  it('should cancel deletion when user clicks cancel button', () => {
    cy.get('[data-testid="notification-item"]').should('have.length', 3);

    cy.get('[data-testid="notification-item"]').eq(1).within(() => {
      cy.get('[data-testid="delete-notification-btn"]').click();
    });

    cy.get('[data-testid="delete-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="cancel-delete-btn"]').click();

    cy.get('[data-testid="delete-confirmation-modal"]').should('not.exist');
    cy.get('[data-testid="notification-item"]').should('have.length', 3);
  });

  it('should handle deletion error gracefully', () => {
    cy.intercept('DELETE', '/api/notifications/*', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('deleteNotificationError');

    cy.get('[data-testid="notification-item"]').first().within(() => {
      cy.get('[data-testid="delete-notification-btn"]').click();
    });

    cy.get('[data-testid="delete-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.wait('@deleteNotificationError');

    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to delete notification');
    cy.get('[data-testid="notification-item"]').should('have.length', 3);
  });

  it('should delete notification using keyboard shortcut', () => {
    cy.get('[data-testid="notification-item"]').eq(1).within(() => {
      cy.get('[data-testid="notification-item"]').focus();
    });

    cy.get('[data-testid="notification-item"]').eq(1).type('{del}');

    cy.get('[data-testid="delete-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.wait('@deleteNotification');

    cy.get('[data-testid="notification-item"]').should('have.length', 2);
  });
});
